pub fn epoch_seed(epoch: u64) -> [u8; 32] {
    let mut hasher = blake3::Hasher::new_keyed(CHV4_MLP_GENESIS_SEED);
    hasher.update(b"CHv4_epoch_weights_v1");
    hasher.update(&epoch.to_le_bytes());
    *hasher.finalize().as_bytes()
}
